    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع الأقواس","math":"<span dir=\"ltr\" class=\"expr\">A = 3 - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">7</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">7</span></span></span>"},{"quoi":"نلاحظ حدّين متقابلين","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">7</span></span></span> و <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">7</span></span></span> متقابلان"},{"quoi":"نحذفهما","math":"<span dir=\"ltr\" class=\"expr\">A = 3 - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span></span>"},{"quoi":"نحسب ما تبقّى","math":"<span dir=\"ltr\" class=\"expr\">3 - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">5</span></span> = <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القيمة المطلقة الأولى","math":"<span dir=\"ltr\" class=\"expr\">|-<span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">7</span></span> + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span>| = |<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">70</span></span>| = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">70</span></span></span>"},{"quoi":"القيمة المطلقة الثانية","math":"<span dir=\"ltr\" class=\"expr\">|-1 + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span>| = |-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">10</span></span>| = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">10</span></span></span>"},{"quoi":"نطرح","math":"<span dir=\"ltr\" class=\"expr\">B = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">70</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">10</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">B = -<span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">35</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نعزل المجهول","math":"<span dir=\"ltr\" class=\"expr\">x = 0 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span></span>"},{"quoi":"القاعدة","math":"العددان اللذان مجموعهما صفر متقابلان"},{"quoi":"نكتب المقابل","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span></span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> + (-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span>) = 0</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننقل الثابت","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span></span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> = -<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">15</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">15</span></span></span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">15</span></span> + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> = <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نلاحظ الحدّ المشترك","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">12</span></span></span> موجود في العضوين"},{"quoi":"نحذفه","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - x = 0</span>"},{"quoi":"القاعدة","math":"الفرق منعدم يعني العددين متساويين"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span></span>"},{"quoi":"نتحقّق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">12</span></span> + (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span>) = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">12</span></span></span>"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"نعزل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|x| = -<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span></span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> = -2</span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-2 &lt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد لا يمكن أن تكون سالبة"},{"quoi":"النتيجة","math":"لا يوجد عدد كسري نسبي x يحقّق المعادلة"}],
