    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس المسبوق بعلامة الطرح","math":"<span dir=\"ltr\" class=\"expr\">- (-y + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - a) = y - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + a</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -x - a + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> + y - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + a</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + (-a + a) + (<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">-(-x - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span>) = x + <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span></span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [(x + <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span>) - (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - y)] = -x - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - y</span>"},{"quoi":"نرفع القوس الأخير","math":"<span dir=\"ltr\" class=\"expr\">- (<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - x - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span>) = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + x + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span></span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">B = x + <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span> - x - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - y - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + x + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span></span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">B = (x - x + x) - y + (<span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = x - y + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span></span>"},{"quoi":"نقلب الفرق المعطى","math":"<span dir=\"ltr\" class=\"expr\">y - x = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span></span>"},{"quoi":"نُظهر المعطى","math":"<span dir=\"ltr\" class=\"expr\">A = (y - x) - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span></span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">A = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span> - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = -<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">20</span></span></span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"ننطلق من الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">B = x - y + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span></span>"},{"quoi":"نُظهر المعطى","math":"<span dir=\"ltr\" class=\"expr\">B = (x - y) + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span></span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">B = (-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">5</span></span>) + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">B = -<span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span></span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">A - B = (-<span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">20</span></span>) - (-<span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span>)</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">A - B = <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">20</span></span></span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">20</span></span> &gt; 0</span>"},{"quoi":"القاعدة","math":"الفرق موجب، إذن A أكبر من B"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A &gt; B</span>"}],
