    rubrique: "ex9", rubriqueNom: "معاملات مضاعفة، ثمّ ثلاث مقارنات", difficulte: "difficile",
    enonce: "<span class=\"q\">1) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = 2c - 2b - <span class=\"frac\"><span class=\"num\">83</span><span class=\"den\">24</span></span></span> حيث <span dir=\"ltr\" class=\"expr\">A = (-a - b + c + <span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">8</span></span>) - (-c + b - a + <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span>)</span><br><span class=\"q\">2) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = 2c - 2b - <span class=\"frac\"><span class=\"num\">83</span><span class=\"den\">24</span></span></span> حيث ليكن <span dir=\"ltr\" class=\"expr\">x</span> عددا كسريا نسبيا؛ قارن بين <span dir=\"ltr\" class=\"expr\">x + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span></span>  و  <span dir=\"ltr\" class=\"expr\">x + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span><br><span class=\"q\">3) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = 2c - 2b - <span class=\"frac\"><span class=\"num\">83</span><span class=\"den\">24</span></span></span> حيث ليكن <span dir=\"ltr\" class=\"expr\">x</span> عددا كسريا نسبيا؛ قارن بين a و b أعدادا كسرية نسبية حيث <span dir=\"ltr\" class=\"expr\">b - a = 2</span> ؛ قارن بين <span dir=\"ltr\" class=\"expr\">-a - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">7</span></span></span>  و  <span dir=\"ltr\" class=\"expr\">-b + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">7</span></span></span><br><span class=\"q\">4) </span>بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = 2c - 2b - <span class=\"frac\"><span class=\"num\">83</span><span class=\"den\">24</span></span></span> حيث ليكن <span dir=\"ltr\" class=\"expr\">x</span> عددا كسريا نسبيا؛ قارن بين a و b أعدادا كسرية نسبية حيث <span dir=\"ltr\" class=\"expr\">b - a = 2</span> ؛ قارن بين ليكن a و b و c أعدادا كسرية نسبية حيث <span dir=\"ltr\" class=\"expr\">a - b = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span> و <span dir=\"ltr\" class=\"expr\">c - a = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span> ؛ احسب <span dir=\"ltr\" class=\"expr\">(a - c) - (a - b)</span> ثمّ استنتج مقارنة b و c",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس المسبوق بعلامة الطرح","math":"<span dir=\"ltr\" class=\"expr\">- (-c + b - a + <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span>) = c - b + a - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span></span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -a - b + c + <span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">8</span></span> + c - b + a - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span></span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = (-a + a) + (c + c) + (-b - b) + (<span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">8</span></span> - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">15</span><span class=\"den\">8</span></span> - <span class=\"frac\"><span class=\"num\">16</span><span class=\"den\">3</span></span> = -<span class=\"frac\"><span class=\"num\">83</span><span class=\"den\">24</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = 2c - 2b - <span class=\"frac\"><span class=\"num\">83</span><span class=\"den\">24</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(x + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span>) - (x + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>) = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"يختفي المجهول","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span></span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> &lt; 0</span>"},{"quoi":"القاعدة","math":"الفرق سالب، إذن العبارة الأولى أصغر"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">4</span></span> &lt; x + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(-a - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">7</span></span>) - (-b + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">7</span></span>) = (b - a) - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">7</span></span></span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">(b - a) - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">7</span></span> = 2 - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">7</span></span></span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">2 - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">7</span></span> = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">7</span></span></span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">7</span></span> &gt; 0</span>"},{"quoi":"القاعدة","math":"الفرق موجب، إذن العبارة الأولى أكبر"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">-a - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">7</span></span> &gt; -b + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">7</span></span></span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نرفع القوسين","math":"<span dir=\"ltr\" class=\"expr\">(a - c) - (a - b) = a - c - a + b</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"يختفي a","math":"<span dir=\"ltr\" class=\"expr\">a - c - a + b = b - c</span>"},{"quoi":"نعبّر بالمعطيين","math":"<span dir=\"ltr\" class=\"expr\">b - c = -(c - a) - (a - b)</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">b - c = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - (-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>)</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">b - c = 2</span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">2 &gt; 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b &gt; c</span>"}],
