    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نرفع القوس الداخلي","math":"<span dir=\"ltr\" class=\"expr\">(-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span>) + (-b - 0,7) = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> - b - 0,7</span>"},{"quoi":"نرفع القوسين الباقيين","math":"<span dir=\"ltr\" class=\"expr\">E = -4 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + b + 0,7 + 2,3 + a</span>"},{"quoi":"نجمّع المجهولين","math":"<span dir=\"ltr\" class=\"expr\">E = (a + b) + (-4 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + 0,7 + 2,3)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-4 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + 0,7 + 2,3 = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span></span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">5 - [a + (-<span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span>)] = 5 - a + <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span></span>"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (2,9 + b) = -2,9 - b</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">F = 5 - a + <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> - 2,9 - b</span>"},{"quoi":"نجمّع المجهولين","math":"<span dir=\"ltr\" class=\"expr\">F = -(a + b) + (5 + <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> - 2,9)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">5 + <span class=\"frac\"><span class=\"num\">6</span><span class=\"den\">5</span></span> - 2,9 = <span class=\"frac\"><span class=\"num\">33</span><span class=\"den\">10</span></span></span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">F = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">33</span><span class=\"den\">10</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = <span class=\"frac\"><span class=\"num\">41</span><span class=\"den\">20</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نترجم « متقابلان »","math":"<span dir=\"ltr\" class=\"expr\">b = -a</span>"},{"quoi":"نحسب المجموع","math":"<span dir=\"ltr\" class=\"expr\">a + b = a + (-a) = 0</span>"},{"quoi":"نستعمل الشكل المبسّط","math":"<span dir=\"ltr\" class=\"expr\">E = (a + b) + (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span>)</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = 0 + (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span>)</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span></span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم المعطى","math":"<span dir=\"ltr\" class=\"expr\">b = a</span>"},{"quoi":"نحسب المجموع","math":"<span dir=\"ltr\" class=\"expr\">a + b = a + a = 2a</span>"},{"quoi":"نستعمل الشكل المبسّط","math":"<span dir=\"ltr\" class=\"expr\">F = -(a + b) + <span class=\"frac\"><span class=\"num\">33</span><span class=\"den\">10</span></span></span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">F = -(2a) + <span class=\"frac\"><span class=\"num\">33</span><span class=\"den\">10</span></span></span>"},{"quoi":"النتيجة بدلالة a","math":"<span dir=\"ltr\" class=\"expr\">F = <span class=\"frac\"><span class=\"num\">33</span><span class=\"den\">10</span></span> - 2a</span>"},{"quoi":"","math":"<b>5)</b>"},{"quoi":"نرفع القوس","math":"<span dir=\"ltr\" class=\"expr\">12 - x - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">10</span></span> = 2</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">12 - <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">10</span></span> = <span class=\"frac\"><span class=\"num\">109</span><span class=\"den\">10</span></span></span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">109</span><span class=\"den\">10</span></span> - x = 2</span>"},{"quoi":"المجهول هو الفرق","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">109</span><span class=\"den\">10</span></span> - 2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">89</span><span class=\"den\">10</span></span></span>"},{"quoi":"","math":"<b>6)</b>"},{"quoi":"نرفع القوس","math":"<span dir=\"ltr\" class=\"expr\">4 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> - x = 0</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">4 - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span></span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> - x = 0</span>"},{"quoi":"المجهول هو الفرق","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span> - 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">4</span></span></span>"},{"quoi":"","math":"<b>7)</b>"},{"quoi":"نعزل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|x| = 2 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span></span>"},{"quoi":"نحسب العضو الثاني","math":"<span dir=\"ltr\" class=\"expr\">2 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">10</span></span> = <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">20</span></span></span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">20</span></span> &gt; 0</span>"},{"quoi":"القاعدة","math":"القيمة المطلقة موجبة، إذن للمعادلة حلاّن متقابلان"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">20</span></span></span>  أو  <span dir=\"ltr\" class=\"expr\">x = -<span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">20</span></span></span>"}],
